//! Port of `internal/ignition/resources/{common,live,target}`.
//!
//! The resource files are embedded from `internal/ignition/resources/<provider>/{files,systemd}`
//! (single copy, shared with the Go code); the directory listings are generated by `build.rs`.

pub mod common;
pub mod live;
pub mod target;

mod embedded {
    include!(concat!(env!("OUT_DIR"), "/embedded.rs"));
}

pub use embedded::{
    COMMON_FILES, COMMON_SYSTEMD, LIVE_FILES, LIVE_SYSTEMD, TARGET_FILES, TARGET_SYSTEMD,
};
